import { Injectable } from '@angular/core';

export interface BrandConfig {
  brand: {
    name: string;
    logo: string;
    logoDark: string;
    icon: string;
  };
  colors: {
    primary: string;
    accent: string;
    secondary: string;
  };
  modules?: {
    allowed: string[];
  };
  app: {
    name: string;
    version: string;
    description: string;
    port: number;
    apiUrl: string;
  };
}

@Injectable({
  providedIn: 'root'
})
export class BrandConfigService {
  private config: BrandConfig = {
    brand: {
      name: 'Beax RM',
      logo: '/config/assets/beax-rm/logo.png',
      logoDark: '/config/assets/beax-rm/logo-dark.png',
      icon: '/config/assets/beax-rm/icon.png'
    },
    colors: {
      primary: '#3B82F6',
      accent: '#F59E0B',
      secondary: '#6B7280'
    },
    app: {
      name: 'Beax Resource Manager',
      version: '1.0.0',
      description: 'Resource Management System',
      port: 4200,
      apiUrl: 'http://localhost:3000/api'
    }
  };

  constructor() {
    this.loadConfigFromEnvironment();
  }

  private loadConfigFromEnvironment(): void {
    // Load configuration from environment variables set by start.js
    if (typeof window !== 'undefined' && (window as any).brandConfig) {
      this.config = (window as any).brandConfig;
    }
  }

  getBrandConfig(): BrandConfig {
    return this.config;
  }

  getConfig(): BrandConfig {
    return this.config;
  }

  getBrandName(): string {
    return this.config.brand.name;
  }

  getAppName(): string {
    return this.config.app.name;
  }

  getLogo(): string {
    return this.config.brand.logo;
  }

  getLogoDark(): string {
    return this.config.brand.logoDark;
  }

  getThemeAwareLogo(isDark: boolean): string {
    return isDark ? this.config.brand.logoDark : this.config.brand.logo;
  }

  getIcon(): string {
    return this.config.brand.icon;
  }

  getColors() {
    return this.config.colors;
  }

  getApiUrl(): string {
    return this.config.app.apiUrl;
  }

  getPrimaryColor(): string {
    return this.config.colors.primary;
  }

  getAllowedModules(): string[] {
    return this.config.modules?.allowed || [];
  }

  isModuleAllowed(moduleId: string): boolean {
    const allowedModules = this.getAllowedModules();
    return allowedModules.length === 0 || allowedModules.includes(moduleId);
  }

  getBrandKey(): string {
    // Extract brand key from API URL or use default
    const apiUrl = this.config.app.apiUrl;
    if (apiUrl.includes(':3002')) return 'raccontixrm';
    if (apiUrl.includes(':3001')) return 'true-process';
    return 'beax-rm';
  }
}